import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';
import DoctorSignin from './pages/doctor/DoctorSignin';
import DoctorSignup from './pages/doctor/DoctorSignup';
import PatientSignin from './pages/patient/PatientSignin';
import PatientSignup from './pages/patient/PatientSignup';
import DoctorsList from './pages/patient/DoctorsList';
import ConsultationForm from './pages/patient/ConsultationForm';

import DoctorProfile from './pages/doctor/DoctorProfile';
import PrescriptionPage from './pages/doctor/PrescriptionPage';
import PrescriptionForm from './components/PrescriptionForm';

const Home = () => (
  <div className="min-h-screen flex flex-col items-center justify-center bg-gray-900 text-white p-4">
    <h1 className="text-4xl font-bold mb-8">Online Prescription Platform</h1>
    <div className="flex gap-6">
      <Link to="/doctor/signin" className="px-6 py-3 bg-purple-600 rounded-lg hover:bg-purple-500 font-semibold transition-colors">
        Doctor Portal
      </Link>
      <Link to="/patient/signin" className="px-6 py-3 bg-teal-600 rounded-lg hover:bg-teal-500 font-semibold transition-colors">
        Patient Portal
      </Link>
    </div>
  </div>
);

function App() {
  return (
    <BrowserRouter>
      <div className="min-h-screen bg-gray-900">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/doctor/signin" element={<DoctorSignin />} />
          <Route path="/doctor/signup" element={<DoctorSignup />} />
          <Route path="/doctor/profile" element={<DoctorProfile />} />
          <Route path="/doctor/prescriptions" element={<PrescriptionPage />} />
          <Route path="/doctor/prescription/:id" element={<PrescriptionForm />} />
          
          <Route path="/patient/signin" element={<PatientSignin />} />
          <Route path="/patient/signup" element={<PatientSignup />} />
          <Route path="/patient/doctors" element={<DoctorsList />} />
          <Route path="/patient/consult/:id" element={<ConsultationForm />} />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
